  const classStudentsModal=selectedClass&&<div className="modal-backdrop report-backdrop"><section className="form-modal" role="dialog" aria-modal="true" aria-labelledby="class-pupils-title"><header><div><div className="section-kicker">CLASS REGISTER</div><h2 id="class-pupils-title">{selectedClass.name} {selectedClass.arm_name||''}</h2><p>Select a pupil to open the student profile.</p></div><button className="icon-button" aria-label="Close class register" onClick={()=>setSelectedClass(null)}><X size={19}/></button></header>{students.filter((student:any)=>String(student.class_arm_id)===String(selectedClass.class_arm_id)).length?<div className="table-wrap"><table><thead><tr><th>Admission number</th><th>Student</th><th>Gender</th><th>Action</th></tr></thead><tbody>{students.filter((student:any)=>String(student.class_arm_id)===String(selectedClass.class_arm_id)).map((student:any)=><tr key={student.id}><td>{student.admission_number}</td><td>{student.first_name} {student.middle_name||''} {student.surname}</td><td>{student.gender||'—'}</td><td><button className="text-link" onClick={()=>{setSelectedClass(null);void openStudentProfile(student.id)}}>View profile</button></td></tr>)}</tbody></table></div>:<div className="module-empty">No pupils are currently enrolled in this class.</div>}<footer><button className="button secondary" onClick={()=>setSelectedClass(null)}>Close</button></footer></section></div>;
